//! The oracle net for tool input schemas.
//!
//! `cc_input_schemas.json` is generated by running the real CC tool modules
//! under `bun` and projecting each `tool.inputSchema` through zod v4's
//! `toJSONSchema` — the same call `utils/zodToJsonSchema.ts` wraps and
//! `utils/api.ts:160` ships to the API as `input_schema`. Regenerate with:
//!
//! ```text
//! cd ../rebuild && bun ../CometixCode/scripts/dump_cc_tool_schemas.mjs \
//!   > ../CometixCode/src/tools/cc_input_schemas.json
//! ```
//!
//! A tool listed in [`MIGRATED`] has had its hand-written JSON literal replaced
//! by the carrier projection, and must reproduce CC's output exactly. Tools not
//! yet listed still carry a literal; adding one here is what "migrated" means.
//!
//! [`OUTSIDE_THE_NET`] records the oracle entries no `fn() -> Tool` can serve,
//! and [`no_oracle_entry_is_silently_dropped`] keeps the two lists exhaustive so
//! a tool cannot fall out of the net unnoticed.

use crate::utils::test_env::{EnvVarGuard, TEST_ENV_LOCK, TestEnvGuard};
use serde_json::Value;

const ORACLE: &str = include_str!("cc_input_schemas.json");

